{
  name = "edge-proxy",
  tasks = [
    {
      name = "proxy",
      runtime = "exec",
      lifecycle = "service",
      config = { command = ["sh", "-c", "exec python3 -u -m http.server $LEGION_PORT_HTTP"] },
      network = { ports = [{ name = "http", static = 18080 }] },
      service = { name = "edge", port = "http", tags = ["edge"] },
      checks = [{ type = "health", kind = "tcp", port = "http", every = "5s", timeout = "2s", unhealthy_after_count = 2 }],
      resources = { cpus = 0.2, memory = 128 },
      permit = [{ key = "pool", operator = "equal", value = "edge" }],
    },
  ],
}

{
  name = "checkout",
  tasks = [
    {
      name = "api",
      group = "api",
      count = 3,
      runtime = "exec",
      lifecycle = "service",
      config = {
        command = ["sh", "-c", "echo \"checkout-api listening on :$LEGION_PORT_HTTP\"; exec python3 -u -m http.server $LEGION_PORT_HTTP"],
        env = { RELEASE = "2026.10.2" },
      },
      network = { ports = [{ name = "http" }] },
      service = { name = "checkout-api", port = "http", tags = ["v2", "public"], meta = { protocol = "http" } },
      checks = [
        { type = "health", kind = "http", path = "/", port = "http", every = "5s", timeout = "2s", unhealthy_after_count = 2 },
      ],
      resources = { cpus = 0.25, memory = 256 },
      permit = [{ key = "pool", operator = "equal", value = "general" }],
    },
    {
      name = "queue-worker",
      group = "workers",
      count = 2,
      runtime = "exec",
      lifecycle = "service",
      config = {
        command = ["sh", "-c", "i=0; while true; do i=$((i+1)); echo \"level=info msg=\\\"processed order batch\\\" batch=$i orders=12 took=340ms\"; sleep 2; done"],
      },
      resources = { cpus = 0.5, memory = 512 },
      permit = [{ key = "pool", operator = "equal", value = "batch" }],
    },
    {
      name = "cache-warmer",
      group = "workers",
      runtime = "exec",
      lifecycle = "service",
      config = {
        command = ["sh", "-c", "echo 'warming 4096 keys from orders-db'; echo 'warn: redis upstream slow (p99 2.4s), retrying' >&2; exec sleep 86400"],
      },
      resources = { cpus = 0.1, memory = 128 },
      permit = [{ key = "pool", operator = "equal", value = "batch" }],
    },
  ],
}

